/* Generated by npm run build. Only public app-shell URLs are cached. */
const PREFIX = 'dispac-shell-'+new URL(self.registration.scope).pathname+'-';
const CACHE = PREFIX+'4822d5f2558ddf6a';
const SHELL = ["./","./index.html","./web/style.css","./config.js","./web/content-data.js","./web/demo-data.js","./web/guide.js","./web/data-service.js","./web/document-preview.js","./web/workspace.js","./web/offline.js","./web/documents.js","./web/app.js"];
const urls = new Set(SHELL.map(path=>new URL(path,self.registration.scope).href));
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll([...urls])).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith(PREFIX)&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{
 if(event.request.method!=='GET'||!urls.has(event.request.url))return;
 event.respondWith(caches.open(CACHE).then(async cache=>(await cache.match(event.request))||fetch(event.request)));
});
